import * as console from "std/console"
export function test(): null {
  console.log("jvm-std-console-log");
  console.error("jvm-std-console-error");
}

import * as str from "std/string"
export function test(): int {
  let ascii: int = str.length("hello");
  let empty: int = str.length("");
  let bytes: int = str.length("héllo");
  return ascii * 100 + empty * 10 + (bytes - 6);
}

import * as str from "std/string"
export function test(): string {
  let whole: string = str.substring("hello", 0, 5);
  let mid: string = str.substring("hello", 1, 4);
  let same: string = str.substring("hello", 2, 2);
  let reversed: string = str.substring("hello", 3, 1);
  let clipped: string = str.substring("abc", 1, 10);
  let past: string = str.substring("abc", 5, 10);
  let neg: string = str.substring("abc", -3, 3);
  return whole + "|" + mid + "|" + same + "|" + reversed + "|" + clipped + "|" + past + "|" + neg;
}

import * as str from "std/string"
export function test(): int {
  let c1: boolean = str.contains("hello world", "world");
  let c2: boolean = str.contains("100%", "%");
  let c3: boolean = str.contains("hello", "");
  let c4: boolean = str.contains("abc", "abcd");
  let s1: boolean = str.startsWith("hello", "hel");
  let s2: boolean = str.startsWith("hello", "");
  let s3: boolean = str.startsWith("hello", "ello");
  let e1: boolean = str.endsWith("hello", "lo");
  let e2: boolean = str.endsWith("", "");
  let e3: boolean = str.endsWith("hello", "xyz");
  let n: int = 0;
  if (c1) { n = n + 1; }
  if (c2) { n = n + 2; }
  if (c3) { n = n + 4; }
  if (!c4) { n = n + 8; }
  if (s1) { n = n + 16; }
  if (s2) { n = n + 32; }
  if (!s3) { n = n + 64; }
  if (e1) { n = n + 128; }
  if (e2) { n = n + 256; }
  if (!e3) { n = n + 512; }
  return n;
}

import * as str from "std/string"
export function test(): string {
  let a: string = str.replace("hello world", "world", "earth");
  let b: string = str.replace("aaa", "a", "b");
  let c: string = str.replace("hello", "xyz", "abc");
  let d: string = str.replace("hello", "", "x");
  let e: string = str.replace("a.b.c", ".", "-");
  let f: string = str.replace("hello", "e", "100%");
  return a + "|" + b + "|" + c + "|" + d + "|" + e + "|" + f;
}

import * as str from "std/string"
import * as console from "std/console"
export function test(): null {
  let parts: string[] = str.split("a,b,c", ",");
  console.log(parts[0]);
