import * as str from "std/string"
export function test(): string {
  let a: string = str.trim("  hello  ");
  let b: string = str.trim("\t\nhello\n");
  let c: string = str.trim("   ");
  let d: string = str.trim("  hello  world  ");
  let e: string = str.trim("hello");
  return a + "|" + b + "|" + c + "|" + d + "|" + e;
}

import * as math from "std/math"
export function test(): int {
  let a: int = math.absInt(-7);
  let b: int = math.absInt(7);
  let c: int = math.minInt(3, 9);
  let d: int = math.maxInt(3, 9);
  let e: int = math.minInt(-5, 2);
  let f: int = math.maxInt(-5, 2);
  let g: int = math.absInt(-9007199254740991);
  let small: int = a + b + c + d + e + f;
  let diff: int = g - 9007199254740968;
  return small + diff;
}

import * as math from "std/math"
export function test(): int {
  let f: number = math.floor(3.8);
  let c: number = math.ceil(3.2);
  let s: number = math.sqrt(9.0);
  let ab: number = math.absNumber(-2.5);
  let fn: number = math.floor(-3.2);
  let cn: number = math.ceil(-3.2);
  if (f === 3.0 && c === 4.0 && s === 3.0 && ab === 2.5 && fn === -4.0 && cn === -3.0) {
    return 1;
  }
  return 0;
}

import * as time from "std/time"
export function test(): int {
  let t: int = time.nowMillis();
  let granularity: int = t % 1000;
  if (t > 1700000000000 && granularity === 0) {
    return 1;
  }
  return 0;
}

